details.query_text:
MATCH ()-[r]->() RETURN r.predicate AS predicate, type(r) AS relationship_type, count(*) AS edge_count ORDER BY edge_count DESC;
MATCH (s)-[r]->(o) WHERE r.predicate IN ['biolink:subclass_of','biolink:similar_to','biolink:chemically_similar_to','biolink:affects','biolink:regulates','biolink:causes','biolink:contributes_to','biolink:has_phenotype','biolink:associated_with','biolink:acts_upstream_of_or_within','biolink:located_in'] RETURN r.predicate AS predicate, labels(s) AS subject_labels, labels(o) AS object_labels, count(*) AS edge_count ORDER BY predicate, edge_count DESC;
MATCH (s)-[r:AFFECTS]->(o) WHERE r.predicate='biolink:affects' AND (s:ChemicalEntity OR s:Drug) RETURN labels(s) AS subject_labels, labels(o) AS object_labels, r.qualified_predicate AS qualified_predicate, r.object_direction_qualifier AS object_direction, r.object_aspect_qualifier AS object_aspect, count(*) AS edge_count ORDER BY edge_count DESC LIMIT 100

MATCH (c:Drug)-[a:AFFECTS]->(g:GeneOrGeneProduct) WHERE a.predicate='biolink:affects' RETURN a.qualified_predicate,a.object_direction_qualifier,a.object_aspect_qualifier,count(*) AS edges,count(DISTINCT c.id+'|'+g.id) AS pairs ORDER BY edges DESC LIMIT 30;
MATCH (g:GeneOrGeneProduct)-[r:CAUSES|CONTRIBUTES_TO]->(d:Disease) WHERE r.predicate IN ['biolink:causes','biolink:contributes_to'] UNWIND coalesce(r.primary_knowledge_sources,['<missing>']) AS source RETURN r.predicate,source,count(*) AS edges,count(DISTINCT g.id+'|'+d.id) AS pairs ORDER BY edges DESC;
MATCH (c:Drug)-[direct:AFFECTS]->(d:Disease) WHERE direct.predicate='biolink:affects' MATCH (c)-[a:AFFECTS]->(g:GeneOrGeneProduct)-[gd:CAUSES|CONTRIBUTES_TO]->(d) WHERE a.predicate='biolink:affects' AND a.qualified_predicate='biolink:causes' AND gd.predicate IN ['biolink:causes','biolink:contributes_to'] AND a.object_aspect_qualifier IN ['activity','activity_or_abundance','expression'] WITH c,d,count(DISTINCT CASE WHEN a.object_direction_qualifier='decreased' AND a.object_aspect_qualifier IN ['activity','activity_or_abundance'] THEN g END) AS dec_activity,count(DISTINCT CASE WHEN a.object_direction_qualifier='increased' AND a.object_aspect_qualifier IN ['activity','activity_or_abundance'] THEN g END) AS inc_activity,count(DISTINCT CASE WHEN a.object_direction_qualifier='decreased' AND a.object_aspect_qualifier='expression' THEN g END) AS dec_expression,count(DISTINCT CASE WHEN a.object_direction_qualifier='increased' AND a.object_aspect_qualifier='expression' THEN g END) AS inc_expression,EXISTS { MATCH (c)-[t:TREATS|AMELIORATES_CONDITION|PREVENTATIVE_FOR_CONDITION]->(d) WHERE t.predicate IN ['biolink:treats','biolink:ameliorates_condition','biolink:preventative_for_condition'] } AS visible RETURN count(*) AS any_pairs,sum(CASE WHEN visible THEN 1 ELSE 0 END) AS any_visible,sum(CASE WHEN dec_activity>0 THEN 1 ELSE 0 END) AS dec_activity_pairs,sum(CASE WHEN dec_activity>0 AND visible THEN 1 ELSE 0 END) AS dec_activity_visible,sum(CASE WHEN inc_activity>0 THEN 1 ELSE 0 END) AS inc_activity_pairs,sum(CASE WHEN inc_activity>0 AND visible THEN 1 ELSE 0 END) AS inc_activity_visible,sum(CASE WHEN dec_expression>0 THEN 1 ELSE 0 END) AS dec_expression_pairs,sum(CASE WHEN dec_expression>0 AND visible THEN 1 ELSE 0 END) AS dec_expression_visible,sum(CASE WHEN inc_expression>0 THEN 1 ELSE 0 END) AS inc_expression_pairs,sum(CASE WHEN inc_expression>0 AND visible THEN 1 ELSE 0 END) AS inc_expression_visible,sum(CASE WHEN dec_activity>=2 THEN 1 ELSE 0 END) AS dec_activity_two_pairs,sum(CASE WHEN dec_activity>=2 AND visible THEN 1 ELSE 0 END) AS dec_activity_two_visible

MATCH (child:ChemicalEntity)-[r:SUBCLASS_OF|DERIVES_FROM|HAS_METABOLITE|CLOSE_MATCH]->(parent:ChemicalEntity) WHERE r.predicate IN ['biolink:subclass_of','biolink:derives_from','biolink:has_metabolite','biolink:close_match'] RETURN r.predicate,count(*) AS edges,count(DISTINCT child.id+'|'+parent.id) AS pairs,count(DISTINCT child) AS children,count(DISTINCT parent) AS parents,sum(CASE WHEN child:Drug THEN 1 ELSE 0 END) AS edges_with_drug_child,sum(CASE WHEN parent:Drug THEN 1 ELSE 0 END) AS edges_with_drug_parent;
MATCH (candidate:Drug)-[relation:SUBCLASS_OF]->(parent:ChemicalEntity)-[e:TREATS|AMELIORATES_CONDITION|PREVENTATIVE_FOR_CONDITION]->(disease:Disease) WHERE relation.predicate='biolink:subclass_of' AND e.predicate IN ['biolink:treats','biolink:ameliorates_condition','biolink:preventative_for_condition'] WITH candidate,disease,count(DISTINCT parent) AS treated_parents,EXISTS { MATCH (candidate)-[t:TREATS|AMELIORATES_CONDITION|PREVENTATIVE_FOR_CONDITION]->(disease) WHERE t.predicate IN ['biolink:treats','biolink:ameliorates_condition','biolink:preventative_for_condition'] } AS visible RETURN count(*) AS pairs,sum(CASE WHEN visible THEN 1 ELSE 0 END) AS visible;
MATCH (candidate:ChemicalEntity)-[relation:DERIVES_FROM]->(parent:ChemicalEntity)-[e:TREATS|AMELIORATES_CONDITION|PREVENTATIVE_FOR_CONDITION]->(disease:Disease) WHERE relation.predicate='biolink:derives_from' AND e.predicate IN ['biolink:treats','biolink:ameliorates_condition','biolink:preventative_for_condition'] WITH candidate,disease,candidate:Drug AS candidate_is_drug,EXISTS { MATCH (candidate)-[t:TREATS|AMELIORATES_CONDITION|PREVENTATIVE_FOR_CONDITION]->(disease) WHERE t.predicate IN ['biolink:treats','biolink:ameliorates_condition','biolink:preventative_for_condition'] } AS visible RETURN count(*) AS pairs,sum(CASE WHEN visible THEN 1 ELSE 0 END) AS visible,sum(CASE WHEN candidate_is_drug THEN 1 ELSE 0 END) AS drug_pairs,sum(CASE WHEN candidate_is_drug AND visible THEN 1 ELSE 0 END) AS drug_visible;
MATCH (parent:ChemicalEntity)-[relation:HAS_METABOLITE]->(candidate:ChemicalEntity) WHERE relation.predicate='biolink:has_metabolite' MATCH (parent)-[e:TREATS|AMELIORATES_CONDITION|PREVENTATIVE_FOR_CONDITION]->(disease:Disease) WHERE e.predicate IN ['biolink:treats','biolink:ameliorates_condition','biolink:preventative_for_condition'] WITH candidate,disease,candidate:Drug AS candidate_is_drug,EXISTS { MATCH (candidate)-[t:TREATS|AMELIORATES_CONDITION|PREVENTATIVE_FOR_CONDITION]->(disease) WHERE t.predicate IN ['biolink:treats','biolink:ameliorates_condition','biolink:preventative_for_condition'] } AS visible RETURN count(*) AS pairs,sum(CASE WHEN visible THEN 1 ELSE 0 END) AS visible,sum(CASE WHEN candidate_is_drug THEN 1 ELSE 0 END) AS drug_pairs,sum(CASE WHEN candidate_is_drug AND visible THEN 1 ELSE 0 END) AS drug_visible

MATCH (c:ChemicalEntity)-[support:MINER_R0001_NONTARGET_TREATMENT_SOURCE_SUPPORT]->(d:Disease) WHERE support.artifact_id='r0001-nontarget-treatment-source-support-v1' MATCH (c)-[a:AFFECTS]->(d) WHERE a.predicate='biolink:affects' WITH c,d,support.source_count AS sources,EXISTS { MATCH (c)-[t:TREATS|AMELIORATES_CONDITION|PREVENTATIVE_FOR_CONDITION]->(d) WHERE t.predicate IN ['biolink:treats','biolink:ameliorates_condition','biolink:preventative_for_condition'] } AS visible RETURN count(*) AS source_ge2_pairs,sum(CASE WHEN visible THEN 1 ELSE 0 END) AS source_ge2_visible,sum(CASE WHEN sources>=3 THEN 1 ELSE 0 END) AS source_ge3_pairs,sum(CASE WHEN sources>=3 AND visible THEN 1 ELSE 0 END) AS source_ge3_visible,sum(CASE WHEN sources>=4 THEN 1 ELSE 0 END) AS source_ge4_pairs,sum(CASE WHEN sources>=4 AND visible THEN 1 ELSE 0 END) AS source_ge4_visible;
MATCH (c:Drug)-[support:MINER_R0001_NONTARGET_TREATMENT_SOURCE_SUPPORT]->(d:Disease) WHERE support.artifact_id='r0001-nontarget-treatment-source-support-v1' MATCH (c)-[a:AFFECTS]->(g:GeneOrGeneProduct)-[gd:CAUSES|CONTRIBUTES_TO]->(d) WHERE a.predicate='biolink:affects' AND a.qualified_predicate='biolink:causes' AND a.object_direction_qualifier='decreased' AND a.object_aspect_qualifier IN ['activity','activity_or_abundance'] AND gd.predicate IN ['biolink:causes','biolink:contributes_to'] WITH c,d,support.source_count AS sources,count(DISTINCT g) AS genes,EXISTS { MATCH (c)-[t:TREATS|AMELIORATES_CONDITION|PREVENTATIVE_FOR_CONDITION]->(d) WHERE t.predicate IN ['biolink:treats','biolink:ameliorates_condition','biolink:preventative_for_condition'] } AS visible RETURN count(*) AS source_ge2_pairs,sum(CASE WHEN visible THEN 1 ELSE 0 END) AS source_ge2_visible,sum(CASE WHEN sources>=3 THEN 1 ELSE 0 END) AS source_ge3_pairs,sum(CASE WHEN sources>=3 AND visible THEN 1 ELSE 0 END) AS source_ge3_visible,sum(CASE WHEN sources>=4 THEN 1 ELSE 0 END) AS source_ge4_pairs,sum(CASE WHEN sources>=4 AND visible THEN 1 ELSE 0 END) AS source_ge4_visible;
MATCH (c:Drug)-[support:MINER_R0001_NONTARGET_TREATMENT_SOURCE_SUPPORT]->(d:Disease) WHERE support.artifact_id='r0001-nontarget-treatment-source-support-v1' MATCH (c)-[direct:AFFECTS]->(d) WHERE direct.predicate='biolink:affects' MATCH (c)-[a:AFFECTS]->(g:GeneOrGeneProduct)-[gd:CAUSES|CONTRIBUTES_TO]->(d) WHERE a.predicate='biolink:affects' AND a.qualified_predicate='biolink:causes' AND a.object_direction_qualifier='decreased' AND a.object_aspect_qualifier IN ['activity','activity_or_abundance'] AND gd.predicate IN ['biolink:causes','biolink:contributes_to'] WITH c,d,support.source_count AS sources,count(DISTINCT g) AS genes,EXISTS { MATCH (c)-[t:TREATS|AMELIORATES_CONDITION|PREVENTATIVE_FOR_CONDITION]->(d) WHERE t.predicate IN ['biolink:treats','biolink:ameliorates_condition','biolink:preventative_for_condition'] } AS visible RETURN count(*) AS source_ge2_pairs,sum(CASE WHEN visible THEN 1 ELSE 0 END) AS source_ge2_visible,sum(CASE WHEN sources>=3 THEN 1 ELSE 0 END) AS source_ge3_pairs,sum(CASE WHEN sources>=3 AND visible THEN 1 ELSE 0 END) AS source_ge3_visible,sum(CASE WHEN sources>=4 THEN 1 ELSE 0 END) AS source_ge4_pairs,sum(CASE WHEN sources>=4 AND visible THEN 1 ELSE 0 END) AS source_ge4_visible

